{
  "name": "Coherent 可调谐超快激光器",
  "name_en": "Coherent tunable ultrafast laser",
  "manufacturer": "Coherent",
  "description": "这是一类由 Coherent 生产的可调谐超快激光器，能够在一定波长范围内输出激光并进行波长调谐，同时支持群时延色散补偿、快门控制和对准模式。该类设备常用于双光子显微、超快光谱、非线性光学及其他需要可调谐短脉冲激光源的实验。",
  "description_en": "This is a tunable ultrafast laser made by Coherent. It provides laser output over a selectable wavelength range and supports wavelength tuning, group-delay-dispersion compensation, shutter control, and alignment mode. Such systems are commonly used in multiphoton microscopy, ultrafast spectroscopy, nonlinear optics, and other experiments requiring a tunable short-pulse laser source.",
  "tag_hints": [
    "tunable ultrafast laser",
    "wavelength tuning",
    "GDD compensation",
    "laser shutter control",
    "alignment mode",
    "multiphoton microscopy",
    "nonlinear optics"
  ],
  "actions": [
    {
      "action_name": "auto-getPower",
      "description": "获取激光器当前输出功率。",
      "description_en": "Get the current laser output power."
    },
    {
      "action_name": "auto-getWavelength",
      "description": "获取当前输出波长。",
      "description_en": "Get the current output wavelength."
    },
    {
      "action_name": "auto-setWavelength",
      "description": "设置目标输出波长。",
      "description_en": "Set the target output wavelength."
    },
    {
      "action_name": "auto-getWavelengthRange",
      "description": "获取可调谐波长范围。",
      "description_en": "Get the tunable wavelength range."
    },
    {
      "action_name": "auto-getGDDMinMax",
      "description": "获取当前波长下允许的群时延色散补偿范围。",
      "description_en": "Get the allowed group-delay-dispersion compensation range at the current wavelength."
    },
    {
      "action_name": "auto-getGDD",
      "description": "获取当前群时延色散补偿值。",
      "description_en": "Get the current group-delay-dispersion compensation value."
    },
    {
      "action_name": "auto-getComp",
      "description": "获取当前色散补偿设置。",
      "description_en": "Get the current dispersion compensation setting."
    },
    {
      "action_name": "auto-setGDD",
      "description": "设置群时延色散补偿值。",
      "description_en": "Set the group-delay-dispersion compensation value."
    },
    {
      "action_name": "auto-clearGDD",
      "description": "清除群时延色散补偿并恢复为无色散补偿状态。",
      "description_en": "Clear the group-delay-dispersion compensation and return to the no-compensation state."
    },
    {
      "action_name": "auto-isTuning",
      "description": "获取波长调谐是否正在进行。",
      "description_en": "Get whether wavelength tuning is currently in progress."
    },
    {
      "action_name": "auto-getShutter",
      "description": "获取激光快门开关状态。",
      "description_en": "Get the laser shutter state."
    },
    {
      "action_name": "auto-setShutter",
      "description": "设置激光快门开关状态。",
      "description_en": "Set the laser shutter state."
    },
    {
      "action_name": "auto-setAlignment",
      "description": "设置对准模式开关状态。",
      "description_en": "Set the alignment mode state."
    },
    {
      "action_name": "auto-getAlignment",
      "description": "获取对准模式状态。",
      "description_en": "Get the alignment mode state."
    },
    {
      "action_name": "auto-clearBuffer",
      "description": "清空激光器通信缓冲区。",
      "description_en": "Clear the laser communication buffer."
    },
    {
      "action_name": "auto-read",
      "description": "读取激光器接口缓冲区中的原始数据。",
      "description_en": "Read raw data from the laser interface buffer."
    },
    {
      "action_name": "auto-write",
      "description": "向激光器发送原始控制数据。",
      "description_en": "Write raw control data to the laser."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与激光器的通信连接。",
      "description_en": "Close the communication connection to the laser."
    },
    {
      "action_name": "auto-readPacket",
      "description": "从激光器读取一条通信数据包。",
      "description_en": "Read a communication packet from the laser."
    }
  ]
}

